def check(inputs, outputs):
    res = []
    try:
        def find(words):
            for k, v in inputs.items():
                kl = k.lower()
                if all(w in kl for w in words):
                    return number(str(v))
            return None
        yrs = find(['elapsed'])
        cost = find(['original cost'])
        life = find(['useful life'])
        salv = find(['salvage'])
        bv = None
        for k, v in outputs.items():
            if isinstance(v, (int, float)):
                bv = float(v)
                break
        if bv is None:
            return res
        tol = 0.01 + 1e-6 * abs(bv)
        if salv is not None and bv < salv - tol:
            res.append('book value %s below salvage value %s' % (bv, salv))
        if cost is not None and bv > cost + tol:
            res.append('book value %s above cost %s' % (bv, cost))
        if bv < -tol:
            res.append('book value %s negative' % bv)
        if yrs is not None and cost is not None and yrs == 0 and abs(bv - cost) > tol:
            res.append('book value %s differs from cost %s at zero years' % (bv, cost))
        if yrs is not None and cost is not None and salv is not None and life is not None:
            if yrs >= 1 and life >= 2 and cost > salv + 0.01 and bv >= cost - tol:
                res.append('book value %s not below cost %s after %s years' % (bv, cost, yrs))
    except Exception:
        pass
    return res

fam_f0003.source:
def check(inputs, outputs):
    res = []
    try:
        def find(d, key):
            for k in d:
                if key in k.lower():
                    return d[k]
            return None
        def num(x):
            if isinstance(x, (int, float)):
                return float(x)
            if isinstance(x, str):
                return number(x)
            return None
        P = number(find(inputs, 'principal') or '')
        rate = number(find(inputs, 'rate') or '')
        term_txt = find(inputs, 'term') or ''
        t = number(term_txt)
        freq_txt = (find(inputs, 'frequency') or '').lower()
        pay = None
        ti = None
        for k, v in outputs.items():
            kl = k.lower()
            if 'payment' in kl:
                pay = num(v)
            if 'interest' in kl:
                ti = num(v)
        fm = {'semimonthly': 24, 'bimonthly': 6, 'biweekly': 26, 'semiannual': 2, 'semi-annual': 2, 'monthly': 12, 'quarterly': 4, 'annual': 1, 'yearly': 1, 'weekly': 52, 'daily': 365}
        m = None
        for name, val in fm.items():
            if name in freq_txt:
                m = val
                break
        years = None
        if t is not None:
            tl = term_txt.lower()
            if 'month' in tl:
                years = t / 12.0
            elif 'year' in tl or 'yr' in tl:
                years = t
        n = None
        if m is not None and years is not None:
            n = m * years
        if pay is not None and P is not None and P > 0 and pay <= 0:
            res.append('payment %s not positive' % pay)
        if ti is not None and P is not None and rate is not None and years is not None:
            simple = P * rate / 100.0
            simple = simple * years
            extra = 0.01 * ((n or 0) + 1)
            if ti > simple + extra + 1e-6 * abs(simple):
                res.append('total interest %s exceeds simple interest %s' % (ti, simple))
        if pay is not None and ti is not None and P is not None and n is not None:
            tol = 0.01 * (n + 2) + 1e-6 * abs(P)
            if abs(pay * n - P - ti) > tol:
                res.append('payment %s x %s payments - principal %s != interest %s' % (pay, n, P, ti))
        if pay is not None and P is not None and n is not None and n > 0:
            if pay < P / n - 0.01 - 1e-6 * P / n:
                res.append('payment %s below principal/n %s' % (pay, P / n))
        if pay is not None and P is not None and m is not None and rate is not None:
            ub = P * (1 + rate / 100.0 / m)
            if pay > ub + 0.01 + 1e-6 * ub:
                res.append('payment %s exceeds principal plus first interest %s' % (pay, ub))
    except Exception:
        pass
    return res
